class AccountingPeriod(CTModel):
    """
    An accounting period is the date range for one finance client’s books, usually a financial year. Accounts and cost centers belong to a period. Closing a period prevents ordinary account and transaction changes; it is separate from making individual transactions immutable.
    """
    client_id: int = Field(validation_alias='clientId', serialization_alias='clientId')
    """Finance client owning this period."""
    end_date: _dt.date = Field(validation_alias='endDate', serialization_alias='endDate')
    """Last date of the period."""
    increment_document_number: bool = Field(validation_alias='incrementDocumentNumber', serialization_alias='incrementDocumentNumber')
    """
    Whether document numbers are incremented automatically. Required in both creation and update.
    """
    is_closed: bool = Field(validation_alias='isClosed', serialization_alias='isClosed')
    """
    Whether the period is closed for ordinary accounting changes. This flag alone does not make transactions immutable.
    """
    start_date: _dt.date = Field(validation_alias='startDate', serialization_alias='startDate')
    """
    First date of the period. Used to match the previous period by subtracting exactly one year.
    """
    donation_receipts_created: OptionalDateTime = Field(default=None, validation_alias='donationReceiptsCreated', serialization_alias='donationReceiptsCreated')
    """Timestamp when donation receipts were marked as created, or null when not yet marked."""
