class AppointmentUpdate(CTModel):
    """
    Full update of an appointment or series. Existing linked bookings and events follow the new schedule. The events list contains only new events; meetingrequests has separate replacement semantics.
    """
    additionals: _t.Optional[_t.List[AppointmentAdditionalCreate]] = Field(default=None)
    end_date: _t.Union[_dt.datetime, _dt.date] = Field(validation_alias='endDate', serialization_alias='endDate')
    """
    End of the base occurrence. For timed appointments it must be later than startDate. For all-day appointments this date is inclusive and may equal startDate for a one-day appointment.
    """
    exceptions: _t.Optional[_t.List[AppointmentExceptionCreate]] = Field(default=None)
    repeat_frequency: _t.Optional[int] = Field(default=None, validation_alias='repeatFrequency', serialization_alias='repeatFrequency')
    """
    Interval between repetitions; use a positive integer for automatic patterns, for example 2 with repeatId=7 for every two weeks. Irrelevant for once/manual patterns.
    """
    repeat_id: _t.Optional[_t.Union[_t.Literal[0, 1, 31, 32, 365, 7, 999], int]] = Field(default=None, validation_alias='repeatId', serialization_alias='repeatId')
    """
    Recurrence pattern: 0 = once, 1 = daily, 7 = weekly, 31 = monthly by date, 32 = monthly by weekday, 365 = yearly, 999 = manually selected dates. Automatic patterns use repeatFrequency and repeatUntil; manual dates use additionals.
    Allowed values: `0`, `1`, `31`, `32`, `365`, `7`, `999`.
    """
    repeat_option: _t.Optional[int] = Field(default=None, validation_alias='repeatOption', serialization_alias='repeatOption')
    """
    For repeatId=32, ordinal of the weekday within the month: 1–5 for first through fifth, 6 for last. The weekday comes from startDate.
    """
    repeat_until: _t.Optional[_dt.date] = Field(default=None, validation_alias='repeatUntil', serialization_alias='repeatUntil')
    """
    Inclusive last date of an automatic series. Supply this with automatic recurrence; omission does not represent an unlimited series in these write endpoints.
    """
    start_date: _t.Union[_dt.datetime, _dt.date] = Field(validation_alias='startDate', serialization_alias='startDate')
    """Start of the base occurrence. For all-day appointments, send YYYY-MM-DD."""
    address: _t.Optional[AppointmentAddressCreate] = Field(default=None)
    """Location entered with an appointment."""
    bookings: _t.Optional[_t.List[AppointmentBookingCreate]] = Field(default=None)
    """Resource reservations matched by resourceId."""
    description: _t.Optional[str] = Field(default=None)
    """Description of the appointment."""
    events: _t.Optional[_t.List[AppointmentEventCreate]] = Field(default=None)
    """
    Only new service-planning events to create. Existing linked events are updated separately when the appointment changes; events no longer matching the series may be deleted.
    """
    inform_owner: _t.Optional[bool] = Field(default=None, validation_alias='informOwner', serialization_alias='informOwner')
    """
    Send an information email to the person on whose behalf the appointment is managed, or its original creator. The workflow skips inactive recipients, the acting user and changes without notable differences.
    """
    is_internal: bool = Field(validation_alias='isInternal', serialization_alias='isInternal')
    """
    Set `false` for a regular appointment. Use `true` only when the appointment is intended to be visible exclusively to signed-in users.
    """
    link: _t.Optional[str] = Field(default=None)
    meetingrequests: _t.Optional[_t.List[MeetingRequestCreate]] = Field(default=None)
    """Invitees for the appointment or series. The field name is lowercase."""
    on_behalf_of_pid: _t.Optional[int] = Field(default=None, validation_alias='onBehalfOfPid', serialization_alias='onBehalfOfPid')
    """
    Person ID on whose behalf the appointment is created. This person is also used as inviter for meeting requests.
    """
    signup: _t.Optional[AppointmentSignupCreate] = Field(default=None)
    """
    Configure groups used to collect registrations for individual appointment occurrences. These are separate ChurchTools groups, not meeting invitations or service-planning events.
    """
    subtitle: _t.Optional[str] = Field(default=None)
    tags: _t.Optional[_t.List[_t.Union[int, str, MetaDataPersonId]]] = Field(default=None)
    """Appointment tags to add, as IDs, names or objects containing id."""
    title: str
    bookings_to_delete: _t.Optional[_t.List[int]] = Field(default=None, validation_alias='bookingsToDelete', serialization_alias='bookingsToDelete')
    """
    IDs of existing appointment bookings to delete. These are booking IDs, not resource IDs. In a split request, the selected scope is removed from these bookings and not recreated for the new appointment.
    """

class Arrangement(CTModel):
    """
    One musical version of a song. Event agenda song items refer to an arrangement ID, allowing different keys, instruments or sources for the same song.
    """
    beat: _t.Optional[str] = Field(default=None)
    """Free-text time signature, such as `4/4` or `6/8`."""
    description: _t.Optional[str] = Field(default=None)
    """Notes about performing this arrangement."""
    duration: _t.Optional[int] = Field(default=None)
    """Expected duration in seconds."""
    key: _t.Optional[_t.Union[_t.Literal['A', 'A#', 'A#m', 'Ab', 'Abm', 'Am', 'B', 'B#', 'B#m', 'Bb', 'Bbm', 'Bm', 'C', 'C#', 'C#m', 'Cb', 'Cbm', 'Cm', 'D', 'D#', 'D#m', 'Db', 'Dbm', 'Dm', 'E', 'E#', 'E#m', 'Eb', 'Ebm', 'Em', 'F', 'F#', 'F#m', 'Fb', 'Fbm', 'Fm', 'G', 'G#', 'G#m', 'Gb', 'Gbm', 'Gm'], str]] = Field(default=None)
    """
    Musical key using the API spelling.
    Allowed values: `A`, `A#`, `A#m`, `Ab`, `Abm`, `Am`, `B`, `B#`, `B#m`, `Bb`, `Bbm`, `Bm`, `C`, `C#`, `C#m`, `Cb`, `Cbm`, `Cm`, `D`, `D#`, `D#m`, `Db`, `Dbm`, `Dm`, `E`, `E#`, `E#m`, `Eb`, `Ebm`, `Em`, ….
    """
    name: str
    """Name distinguishing this version from other arrangements."""
    source_id: _t.Optional[int] = Field(default=None, validation_alias='sourceId', serialization_alias='sourceId')
    """ID of a song source, such as a hymnal or songbook, from GET /song/sources."""
    source_reference: _t.Optional[str] = Field(default=None, validation_alias='sourceReference', serialization_alias='sourceReference')
    """
    Location within the selected source, such as a song number or page. Only used with sourceId.
    """
    tempo: _t.Optional[int] = Field(default=None)
    """Tempo in beats per minute."""
    deprecated: ArrangementDeprecated = Field(validation_alias='@deprecated', serialization_alias='@deprecated')
    bpm: _t.Optional[str] = Field(default=None, deprecated=True)
    """Compatibility alias for tempo, serialized as a string or `null`."""
    files: _t.List[FileOrLink]
    """List of files uploaded to that arrangement"""
    id: int
    is_default: bool = Field(validation_alias='isDefault', serialization_alias='isDefault')
    """Whether this arrangement is marked as a default for its song."""
    key_of_arrangement: _t.Optional[_t.Union[_t.Literal['A', 'A#', 'A#m', 'Ab', 'Abm', 'Am', 'B', 'B#', 'B#m', 'Bb', 'Bbm', 'Bm', 'C', 'C#', 'C#m', 'Cb', 'Cbm', 'Cm', 'D', 'D#', 'D#m', 'Db', 'Dbm', 'Dm', 'E', 'E#', 'E#m', 'Eb', 'Ebm', 'Em', 'F', 'F#', 'F#m', 'Fb', 'Fbm', 'Fm', 'G', 'G#', 'G#m', 'Gb', 'Gbm', 'Gm'], str]] = Field(default=None, validation_alias='keyOfArrangement', serialization_alias='keyOfArrangement', deprecated=True)
    """
    Use 'key' instead
    Allowed values: `A`, `A#`, `A#m`, `Ab`, `Abm`, `Am`, `B`, `B#`, `B#m`, `Bb`, `Bbm`, `Bm`, `C`, `C#`, `C#m`, `Cb`, `Cbm`, `Cm`, `D`, `D#`, `D#m`, `Db`, `Dbm`, `Dm`, `E`, `E#`, `E#m`, `Eb`, `Ebm`, `Em`, ….
    """
    links: _t.List[FileOrLink]
    """List of links "uploaded" to that arrangement"""
    meta: MetaDataEntityId
    note: _t.Optional[str] = Field(default=None, deprecated=True)
    """Use 'description' instead"""
    source: _t.Optional[SongSource] = Field(default=None)
    """Source associated with this arrangement, or `null` when none is assigned."""
    source_name: _t.Optional[str] = Field(default=None, validation_alias='sourceName', serialization_alias='sourceName', deprecated=True)
    """Source abbreviation if set, otherwise its name, or `null` when no source is assigned."""

