class Bulkletter(CTModel):
    """
    A mail-merge rendering job. Generates one PDF per selected recipient (or address group) and makes those PDFs available together in a ZIP archive. It does not send email or postal mail. The legacy response uses mixed snake_case and camelCase fields.
    """
    content: str
    """HTML content of the bulkletter, may contain placeholders."""
    created: _t.Optional[str] = Field(default=None)
    """Legacy database timestamp in Y-m-d H:i:s format, without timezone; nullable in storage."""
    created_pid: str
    """ID of the person that created the bulkletter (returned as string)."""
    file_id: int = Field(validation_alias='fileId', serialization_alias='fileId')
    """Generated ZIP archive file ID, or 0 before a file has been stored."""
    group_id: int = Field(validation_alias='groupId', serialization_alias='groupId')
    """Optional group the bulkletter is associated with. `0` if no group is set."""
    html_template_id: int = Field(validation_alias='htmlTemplateId', serialization_alias='htmlTemplateId')
    """ID of the HTML template used to render the bulkletter."""
    id: int
    name: str
    status: _t.Union[_t.Literal['DONE', 'ERROR', 'IN_PROGRESS', 'TODO'], str]
    """
    Rendering lifecycle: TODO, IN_PROGRESS, DONE or ERROR. Completion and storing the archive are separate steps; check fileId/url as well as status.
    Allowed values: `DONE`, `ERROR`, `IN_PROGRESS`, `TODO`.
    """
    updated: _t.Optional[str] = Field(default=None)
    """Legacy database timestamp in Y-m-d H:i:s format, without timezone; nullable in storage."""
    url: _t.Optional[str] = Field(default=None)
    """
    Relative download URL of the ZIP archive containing individual PDFs. May be empty or null before the archive is available; resolve relative to the CT base URL.
    """

class BulkletterCreate(CTModel):
    """
    Creates a mail-merge job using an HTML template and selected person IDs. Requires edit bulkletter permission and visibility of the template. Successful creation only schedules rendering.
    """
    content: str
    """
    HTML inserted into the template’s {{content}} slot. Supports person/group placeholders. Non-empty; the literal string 0 is rejected.
    """
    group_by_household: bool = Field(validation_alias='groupByHousehold', serialization_alias='groupByHousehold')
    """
    Group persons by identical street, address addition, postal code, city and country. Only persons with street, postal code and city are grouped. The first person returned for each address represents it; this is not a family-relationship or household-head calculation.
    """
    group_id: _t.Optional[int] = Field(default=None, validation_alias='groupId', serialization_alias='groupId')
    """Optional group used as placeholder context, not as a restriction on personIds."""
    html_template_id: int = Field(validation_alias='htmlTemplateId', serialization_alias='htmlTemplateId')
    """ID of the HTML template used to render the bulkletter."""
    name: str
    """Job name. Non-empty; the literal string 0 is rejected by the current validator."""
    person_ids: _t.List[int] = Field(validation_alias='personIds', serialization_alias='personIds')
    """
    Person IDs to render. Duplicate IDs are resolved through the person lookup; unknown IDs do not create recipient rows.
    """

