class Checkin(CTModel):
    """
    Attendance confirmation for an existing person. The embedded meeting contains refreshed attendance statistics.
    """
    group: DomainObjectGroup
    group_meeting: GroupMeeting = Field(validation_alias='groupMeeting', serialization_alias='groupMeeting')
    """
    One dated occurrence of a group meeting, used to record attendance, guest counts and feedback. It is separate from the group itself and its memberships. No independent end time is stored. Cancellation and completion are separate flags; completion locks check-in changes.
    """
    person: DomainObjectPerson
    """Person as Domain Object"""
    total_checked_in: int = Field(validation_alias='totalCheckedIn', serialization_alias='totalCheckedIn')
    """Number of participants currently checked in at this meeting."""

class CheckinCreate(CTModel):
    """
    Records attendance for one existing person at one group meeting. Supply exactly one non-null date or groupMeetingId; the other may be omitted or null.
    """
    date: OptionalDateTime = Field(default=None)
    """
    Exact start timestamp of a meeting in this group. An existing meeting at that timestamp is reused; otherwise a meeting is created.
    """
    group_meeting_id: _t.Optional[int] = Field(default=None, validation_alias='groupMeetingId', serialization_alias='groupMeetingId')
    """ID of an existing meeting belonging to the path group."""
    printer_id: _t.Optional[int] = Field(default=None, validation_alias='printerId', serialization_alias='printerId')
    """optional printer ID, if a name tag should be printed out"""
    token: _t.Optional[str] = Field(default=None)
    """
    Optional ticket token for this person and group. The ticket is marked used before attendance is recorded; later failures can leave it used.
    """

class CheckinMembershipCreate(CTModel):
    """
    Membership to create before a separate attendance check-in. The group’s default role and normal active membership status are used; the origin is check-in. No meeting attendance or label printing is performed here.
    """
    fields: _t.Optional[StrMap[_t.Any]] = Field(default=None)
    """
    Group-member custom field values keyed by field ID. Definitions and allowed options belong to the selected group. Omitted fields use membership defaults. POST and PUT currently differ in validation, so clients should submit correctly typed values for the field definition.
    """
    id: int
    """
    Target group ID. Supply an integer even though the enclosing validator does not validate this nested key explicitly.
    """
    ignore_group_size: _t.Optional[bool] = Field(default=None, validation_alias='ignoreGroupSize', serialization_alias='ignoreGroupSize')
    """
    Allows admission even when the group is full; no additional override permission is checked here.
    """
    person_fields: StrMap[_t.Any] = Field(validation_alias='personFields', serialization_alias='personFields')
    """
    Person fields to update after membership creation, keyed by API field name. Only names configured as person fields for this group are applied; other names are ignored. Send an empty object when no changes are needed.
    """

