class CostCenter(CTModel):
    """
    A cost center assigns income and expenses to a purpose, project or group within one accounting period. Budgets and balances use integer minor currency units (for example cents). Linking a group also enables access through group-internal finance permissions. Includes the linked group, or null when there is none.
    """
    accounting_period_id: int = Field(validation_alias='accountingPeriodId', serialization_alias='accountingPeriodId')
    annotation: _t.Optional[str] = Field(default=None)
    budget: _t.Optional[int] = Field(default=None)
    """Budget is in cent."""
    budget_balance: _t.Optional[int] = Field(default=None, validation_alias='budgetBalance', serialization_alias='budgetBalance')
    """
    Budget plus cash-account income minus cash-account expenses, in minor currency units. Null without a budget or before calculation.
    """
    budget_balance_last_period: _t.Optional[int] = Field(default=None, validation_alias='budgetBalanceLastPeriod', serialization_alias='budgetBalanceLastPeriod')
    """
    Remaining budget of the matching cost center in the previous period, in minor currency units. Null when unavailable or not calculated; an unmatched center can have 0.
    """
    budget_last_period: _t.Optional[int] = Field(default=None, validation_alias='budgetLastPeriod', serialization_alias='budgetLastPeriod')
    """
    Budget of the cost center with the same number in the previous period of this client, in minor currency units. Null when unavailable or not calculated.
    """
    budget_spent: _t.Optional[int] = Field(default=None, validation_alias='budgetSpent', serialization_alias='budgetSpent')
    """
    Cash-account expenses minus cash-account income, in minor currency units. Can be negative. Null if not calculated, for example immediately after creation.
    """
    id: int
    meta: MetaDataEntityId
    name: _t.Optional[str] = Field(default=None)
    number: str
    group: _t.Optional[DomainObjectGroup] = Field(default=None)
    """
    Linked group as a domain object, or null. The response does not include a separate groupId.
    """

class CostCenterBulkCreate(CTModel):
    """Cost centers to create. Each item may select its own accounting period and group."""
    cost_centers: _t.List[CostCenterCreate] = Field(validation_alias='costCenters', serialization_alias='costCenters')

class CostCenterCreate(CTModel):
    """
    A cost center assigns income and expenses to a purpose, project or group within one accounting period. Budgets and balances use integer minor currency units (for example cents). Linking a group also enables access through group-internal finance permissions.
    """
    accounting_period_id: int = Field(validation_alias='accountingPeriodId', serialization_alias='accountingPeriodId')
    """Existing, open accounting period owning this cost center."""
    annotation: _t.Optional[str] = Field(default=None)
    """Optional trimmed note. Omitted, null or blank clears it."""
    budget: _t.Optional[int] = Field(default=None)
    """
    Optional budget in minor currency units, for example 3200 for EUR 32.00. Omitted or null removes the budget.
    """
    group_id: _t.Optional[int] = Field(default=None, validation_alias='groupId', serialization_alias='groupId')
    """Optional linked group. Omitted or null removes the link, including on update."""
    name: str
    """Trimmed name, unique within the accounting period. Supply a nonblank name when creating."""
    number: str
    """
    Trimmed identifier, unique within the accounting period. Leading zeros are preserved; letters are accepted, although list ordering compares the integer value.
    """

class CostCenterStatementReportCreate(CTModel):
    """
    Optional account-report options. A missing body selects the entire accounting period as a PDF.
    """
    end_date: _t.Optional[_dt.date] = Field(default=None, validation_alias='endDate', serialization_alias='endDate')
    """
    Last document date to include. Omission or null defaults to the corresponding accounting-period boundary. The final endDate must be on or after startDate.
    """
    format: _t.Optional[_t.Union[_t.Literal['csv', 'pdf', 'xlsx'], str]] = Field(default=None)
    """
    PDF creates a file and returns its URL with HTTP 201. CSV/XLSX return the file directly with HTTP 200. Accept: text/html overrides this selection.
    Allowed values: `csv`, `pdf`, `xlsx`.
    """
    start_date: _t.Optional[_dt.date] = Field(default=None, validation_alias='startDate', serialization_alias='startDate')
    """
    First document date to include. Omission or null defaults to the corresponding accounting-period boundary. The final endDate must be on or after startDate.
    """
    include_rebookings: _t.Optional[bool] = Field(default=None, validation_alias='includeRebookings', serialization_alias='includeRebookings')
    """Include transactions classified as internal rebookings in the cost-center report."""
    type_: _t.Optional[_t.Union[_t.Literal['csv', 'pdf', 'xlsx'], str]] = Field(default=None, validation_alias='type', serialization_alias='type', deprecated=True)
    """
    Legacy alias for format.
    Allowed values: `csv`, `pdf`, `xlsx`.
    """

