    """Status code from DRV"""
    drv_status_message: _t.Optional[str] = Field(default=None, validation_alias='drvStatusMessage', serialization_alias='drvStatusMessage')
    """Status message from DRV"""
    extra_status_code: _t.Optional[str] = Field(default=None, validation_alias='extraStatusCode', serialization_alias='extraStatusCode')
    """Most recent eXTra transport/status code."""
    extra_status_message: _t.Optional[str] = Field(default=None, validation_alias='extraStatusMessage', serialization_alias='extraStatusMessage')
    """Most recent eXTra status message."""
    file_id: _t.Optional[int] = Field(default=None, validation_alias='fileId', serialization_alias='fileId')
    """ID of the generated export file in cc_file"""
    id: int
    """Submission ID"""
    meta: MetaDataEntityId
    periods: _t.List[EubpSubmissionPeriod]
    """
    One row per affected client and requested year, including rows without a matching accounting period.
    """
    reference_date: OptionalDateTime = Field(default=None, validation_alias='referenceDate', serialization_alias='referenceDate')
    """
    Reference date for the audit (Stichtag der Prüfung) Serialized as an ISO timestamp including timezone, even though creation accepts a calendar date. Serialized as an ISO timestamp including timezone, even though creation accepts a calendar date.
    """
    sent_date: OptionalDateTime = Field(default=None, validation_alias='sentDate', serialization_alias='sentDate')
    """Timestamp when submission was sent"""
