    group_meeting: GroupSettingsGroupMeeting = Field(validation_alias='groupMeeting', serialization_alias='groupMeeting')
    in_statistic: bool = Field(validation_alias='inStatistic', serialization_alias='inStatistic')
    inform_leader: bool = Field(validation_alias='informLeader', serialization_alias='informLeader')
    """Inform leader via e-mail about changes."""
    is_hidden: bool = Field(validation_alias='isHidden', serialization_alias='isHidden')
    is_open_for_members: bool = Field(validation_alias='isOpenForMembers', serialization_alias='isOpenForMembers')
    """Indicator if people can sign up for group membership."""
    is_public: bool = Field(validation_alias='isPublic', serialization_alias='isPublic')
    max_members: _t.Optional[int] = Field(default=None, validation_alias='maxMembers', serialization_alias='maxMembers')
    """The maximum number of group members in counted roles and statuses."""
    new_member: GroupSettingsNewMember = Field(validation_alias='newMember', serialization_alias='newMember')
