    posts_enabled: bool = Field(validation_alias='postsEnabled', serialization_alias='postsEnabled')
    qr_code_checkin: bool = Field(validation_alias='qrCodeCheckin', serialization_alias='qrCodeCheckin')
    """QR Codes are sent to participants, which can be used during check-in"""
    qr_code_checkin_automatic_email: bool = Field(validation_alias='qrCodeCheckinAutomaticEmail', serialization_alias='qrCodeCheckinAutomaticEmail')
