class GroupSignUpConditions(CTModel):
    """
    Specifies conditions required to sign up in this group. Not all conditions apply to any user, e.g. some of the conditions only apply to users that are not logged in.
    """
    deprecated: StrMap[str] = Field(validation_alias='@deprecated', serialization_alias='@deprecated')
    at_least_one_leader_can_create_new_person: bool = Field(validation_alias='atLeastOneLeaderCanCreateNewPerson', serialization_alias='atLeastOneLeaderCanCreateNewPerson')
    can_contact_leader: bool = Field(validation_alias='canContactLeader', serialization_alias='canContactLeader')
    """
    If false, none of the group's leaders have an email address set. Only persons already signed in can sign up.
    """
    can_sign_up: bool = Field(validation_alias='canSignUp', serialization_alias='canSignUp')
    can_sign_up_as_new_person: bool = Field(validation_alias='canSignUpAsNewPerson', serialization_alias='canSignUpAsNewPerson')
    default_role_set_in_group: _t.Optional[bool] = Field(default=None, validation_alias='defaultRoleSetInGroup', serialization_alias='defaultRoleSetInGroup', deprecated=True)
    end_date_not_passed: bool = Field(validation_alias='endDateNotPassed', serialization_alias='endDateNotPassed')
    """If false, the group's end date has passed and nobody can sign up."""
    group_allows_waitinglist: bool = Field(validation_alias='groupAllowsWaitinglist', serialization_alias='groupAllowsWaitinglist')
    group_has_leader: bool = Field(validation_alias='groupHasLeader', serialization_alias='groupHasLeader')
    """If false, no leader is set for the group and nobody can sign up."""
    group_has_space_for_requests: bool = Field(validation_alias='groupHasSpaceForRequests', serialization_alias='groupHasSpaceForRequests')
    group_has_space_on_waitinglist: bool = Field(validation_alias='groupHasSpaceOnWaitinglist', serialization_alias='groupHasSpaceOnWaitinglist')
    group_is_active: bool = Field(validation_alias='groupIsActive', serialization_alias='groupIsActive')
    """If false, the group is not in active state and nobody can sign up."""
