class LockedPermission(CTModel):
    """
    A global restriction on changing one permission selection, across assignment domains. It does not revoke existing grants. Authorized persons can still modify locked assignments.
    """
    auth_id: int = Field(validation_alias='authId', serialization_alias='authId')
    """
    Numeric permission definition ID; locks may include group-internal (+) permissions as well as global permissions.
    """
    data_id: _t.Optional[int] = Field(default=None, validation_alias='dataId', serialization_alias='dataId')
    """
    Concrete data selection, -1 to lock all selections, or null for a boolean permission. The repository always returns this field.
    """

class LockedPermissionChange(CTModel):
    """
    Permission selection to lock or unlock. dataId may be omitted for boolean permissions; selectable permissions require a non-null integer.
    """
    auth_id: int = Field(validation_alias='authId', serialization_alias='authId')
    """
    Numeric permission definition ID; locks may include group-internal (+) permissions as well as global permissions.
    """
    data_id: _t.Optional[int] = Field(default=None, validation_alias='dataId', serialization_alias='dataId')
    """
    Omit or use null for a boolean permission. For a selectable permission provide a concrete ID or -1 for all selections. Selection existence/range is currently not validated; do not send the internal storage sentinel -2147483648.
    """

class LockedPermissionState(CTModel):
    """"""
    is_current_user_authorized_person: bool = Field(validation_alias='isCurrentUserAuthorizedPerson', serialization_alias='isCurrentUserAuthorizedPerson')
    """
    Whether the current person belongs to the installation’s authorized contact-person list. This is distinct from permission-administration rights.
    """
    permissions: _t.List[LockedPermission]
    """
    All stored locks ordered by authId and dataId, including any locks for inactive or obsolete definitions.
    """

class LockedPermissionUpdate(CTModel):
    """
    Atomic additions/removals, not replacement of the full lock list. Both lists are required; empty lists are valid.
    """
    add: _t.List[LockedPermissionChange]
    """Locks to add. Duplicates are collapsed and existing rows are retained."""
    remove: _t.List[LockedPermissionChange]
    """
    Exact locks to remove. Missing rows are ignored. Removing -1 does not remove separate concrete-value locks.
    """

class Log(CTModel):
    """
    ChurchTools writes log messages for many events and changes. This can be an update for a person or the deletion of an event. You can use the log to debug your system and follow error messages. This is a versitile tool.
    """
    date: _dt.datetime
    """Timestamp of log"""
    domain_id: int = Field(validation_alias='domainId', serialization_alias='domainId')
    """Analog to the domain type, the ID is the explicit resource."""
    domain_type: str = Field(validation_alias='domainType', serialization_alias='domainType')
    """The domain type tells us, where in ChurchTools the action was performed."""
    id: int
    level: int
    """The log level indicates the importance. 1 = Warning, 2 = Notice, 3 = Info."""
    message: str
    person: _t.Optional[DomainObjectPerson] = Field(default=None)
    person_id: int = Field(validation_alias='personId', serialization_alias='personId')
    """
    If the person ID is `-1`, that means, no person but the system itself has logged that message.
    """
    person_name: str = Field(validation_alias='personName', serialization_alias='personName')
    """
    The name of the person, who caused the log message. This is stored in the log, because the person could be deleted later. So we have the name in the log, even if the person is deleted.
    """
    simulate_person: _t.Optional[DomainObjectPerson] = Field(default=None, validation_alias='simulatePerson', serialization_alias='simulatePerson')
    simulate_person_id: _t.Optional[int] = Field(default=None, validation_alias='simulatePersonId', serialization_alias='simulatePersonId')
    """
    If a person is simulated by an administrator, we log the personId as well. This makes it possible to see if a person did the action or an admin, who simulated that person.
    """

