class OpenMeetingRequest(CTModel):
    """
    Unanswered invitation with a remaining occurrence. The next occurrence dates are populated for this view; the embedded appointment retains the stored series data.
    """
    accepted: _t.Optional[bool] = Field(default=None, deprecated=True)
    """Use `state` instead"""
    appointment: AppointmentBase
    """
    Stored calendar appointment defining a single occurrence or a series. id identifies the whole stored appointment; pair it with a local occurrence start date to address a particular occurrence. startDate/endDate are the base occurrence, not necessarily the occurrence currently being displayed. Service-planning events, registration groups, bookings and meeting requests are separate linked resources.
    """
    appointment_id: _t.Optional[int] = Field(default=None, validation_alias='appointmentId', serialization_alias='appointmentId', deprecated=True)
    """Use `appointment` instead"""
    event_date: OptionalDateTime = Field(default=None, validation_alias='eventDate', serialization_alias='eventDate', deprecated=True)
    """
    Start of the stored appointment or series, not necessarily its next occurrence. Use nextStartDate when available.
    """
    id: int
    """ID of this meeting request."""
    invitee: MeetingRequestInvitee
    """Person invited to the appointment."""
    inviter: MeetingRequestInviter
    """
    Person issuing the invitation, derived from onBehalfOfPid when set or the user creating the request.
    """
    mail_send_date: OptionalDateTime = Field(default=None, validation_alias='mailSendDate', serialization_alias='mailSendDate')
    """When the invitation mail was sent, or null."""
    meta: MetaDataEntityId
    next_end_date: _dt.datetime = Field(validation_alias='nextEndDate', serialization_alias='nextEndDate')
    """Next start plus the stored appointment duration, truncated to whole minutes."""
    next_start_date: _dt.datetime = Field(validation_alias='nextStartDate', serialization_alias='nextStartDate')
    """Start of the next occurrence found by recurrence calculation."""
    person: _t.Optional[MeetingRequestPerson] = Field(default=None, deprecated=True)
    """Use `invitee` instead"""
    response_date: None = Field(validation_alias='responseDate', serialization_alias='responseDate')
    """No answer has been recorded. Tentative answers have a response date and are excluded."""
    state: _t.Union[_t.Literal['accepted', 'declined', 'pending', 'tentative'], str]
    """
    Response state: pending awaits an answer, accepted confirms attendance, declined refuses, tentative is undecided.
    Allowed values: `accepted`, `declined`, `pending`, `tentative`.
    """

