class PermissionAssignmentSummary(CTModel):
    """
    Assignment breakdown for one global permission selection. effectivePersonCount includes all effective sources, but the breakdown only groups status, group-type-role, group-role and direct-person sources. Logged-in defaults, public-user rights and super-admin status can therefore contribute to the total without appearing in assignments.
    """
    assignments: PermissionAssignmentSummaryAssignments
    """
    Nonempty assignment sources only. Status, group-type and group entries are sorted numerically by their IDs; role IDs within them are unique and sorted. Counts are distinct per entry but overlap across entries.
    """
    auth_id: int = Field(validation_alias='authId', serialization_alias='authId')
    """Numeric permission key"""
    data_id: _t.Optional[int] = Field(default=None, validation_alias='dataId', serialization_alias='dataId')
    """Selected permission value, or null for boolean permissions"""
    effective_person_count: int = Field(validation_alias='effectivePersonCount', serialization_alias='effectivePersonCount')
    """Total number of distinct non-archived persons with the effective permission"""

class PermissionAssignmentSummaryAssignments(CTModel):
    """
    Nonempty assignment sources only. Status, group-type and group entries are sorted numerically by their IDs; role IDs within them are unique and sorted. Counts are distinct per entry but overlap across entries.
    """
