class RelationshipType(CTModel):
    """
    Definition of a relationship between two persons, such as Parent / Child or Friend / Friend. This is catalog metadata, not an actual relationship between named persons. The two role labels describe its sides; identical stored labels make it undirected in the backend. Security and export settings concern use of relationships of this type.
    """
    degree_name_a: str = Field(validation_alias='degreeNameA', serialization_alias='degreeNameA')
    """Role label for side A. Identical labels on both sides make the type undirected."""
    degree_name_b: str = Field(validation_alias='degreeNameB', serialization_alias='degreeNameB')
    """Role label for side B and counterpart of `degreeNameA`."""
    export_title: _t.Optional[str] = Field(default=None, validation_alias='exportTitle', serialization_alias='exportTitle')
    """
    Heading for the combined export column. The export otherwise uses the type name or synthesized role labels.
    """
    include_in_export: bool = Field(validation_alias='includeInExport', serialization_alias='includeInExport')
    """
    Whether selected export values from both relationship directions are combined in one column. `false` still permits separate-direction export.
    """
    name: _t.Optional[str] = Field(default=None)
    """
    Stored type name or translation key. Use `nameTranslated` for the synthesized display label.
    """
    security_level_id: int = Field(validation_alias='securityLevelId', serialization_alias='securityLevelId')
    """Security level configured for relationships of this type."""
    sort_key: int = Field(validation_alias='sortKey', serialization_alias='sortKey')
    """
    Primary ascending catalog sort key. Ties are ordered by stored name, not by the translated or synthesized display name.
    """
    degree_name_a_translated: str = Field(validation_alias='degreeNameATranslated', serialization_alias='degreeNameATranslated')
    """Side A role label translated for the current language."""
    degree_name_b_translated: str = Field(validation_alias='degreeNameBTranslated', serialization_alias='degreeNameBTranslated')
    """Side B role label translated for the current language."""
    function_keys: _t.List[_t.Union[_t.Literal['nodelete', 'noduplicate', 'openduplicate'], str]] = Field(validation_alias='functionKeys', serialization_alias='functionKeys')
    """
    Built-in behavior flags; always an array, empty for ordinary custom types. `nodelete` protects the type from deletion; `noduplicate` and `openduplicate` identify types used by duplicate-person handling.
    Allowed values: `nodelete`, `noduplicate`, `openduplicate`.
    """
    id: int
    """Relationship-type ID used when creating or reading a relationship between persons."""
    name_translated: str = Field(validation_alias='nameTranslated', serialization_alias='nameTranslated')
    """Translated display name, using the translated side labels as a fallback."""

