class Resource(CTModel):
    """
    An individual bookable resource, such as a room, vehicle or item of equipment. A resource type groups similar resources. Bookings reserve this resource for specific dates.
    """
    admin_ids: _t.List[int] = Field(validation_alias='adminIds', serialization_alias='adminIds')
    """
    Persons responsible for this resource. Resource administrators can view and administer its bookings; changing resource settings still requires permission to edit resource master data.
    """
    description: _t.Optional[str] = Field(default=None)
    """Additional information about the resource, such as capacity or available equipment."""
    i_cal_location: _t.Optional[str] = Field(default=None, validation_alias='iCalLocation', serialization_alias='iCalLocation')
    """Location text used in the resource’s iCalendar export."""
    is_auto_accept: bool = Field(validation_alias='isAutoAccept', serialization_alias='isAutoAccept')
    """
    Automatically approves pending bookings when there are no conflicts. For virtual resources, automatic approval bypasses the conflict check. This does not grant permission to edit resource settings.
    """
    is_virtual: bool = Field(validation_alias='isVirtual', serialization_alias='isVirtual')
    """
    Whether this is a virtual resource. Virtual bookings have a separate creation permission and bypass conflicts when checking automatic approval.
    """
    location: _t.Optional[str] = Field(default=None)
    """Internal location of the resource."""
    name: str
    """Name of the individual resource, for example a room or vehicle."""
    quantity: int
    """Number of units available for simultaneous bookings."""
    random_string: _t.Optional[str] = Field(default=None, validation_alias='randomString', serialization_alias='randomString')
    """
    Access token used by the legacy public iCalendar export. Changing or clearing it invalidates subscriptions using the previous token.
    """
    resource_type_id: int = Field(validation_alias='resourceTypeId', serialization_alias='resourceTypeId')
    """
    Resource type used to group this resource, such as rooms or vehicles. Resource types are available from `/resourcetypes`.
    """
    sort_key: int = Field(validation_alias='sortKey', serialization_alias='sortKey')
    """Sort value for displaying resources."""
    does_require_cal_entry: _t.Optional[bool] = Field(default=None, validation_alias='doesRequireCalEntry', serialization_alias='doesRequireCalEntry', deprecated=True)
    """Use `needsAppointment` instead."""
    id: int
    involved_persons_domain_objects: _t.Optional[BookingCalculatedWithIncludesBaseResourceInvolvedPersonsDomainObjects] = Field(default=None, validation_alias='involvedPersonsDomainObjects', serialization_alias='involvedPersonsDomainObjects')
    """
    Included with `include[]=involvedPersonsDomainObjects`. Contains person references for resolvable `adminIds`; missing persons are omitted.
    """
    meta: MetaDataEntityId
    name_translated: str = Field(validation_alias='nameTranslated', serialization_alias='nameTranslated')
    """Resource name translated for the current language, falling back to name."""
    needs_appointment: _t.Optional[bool] = Field(default=None, validation_alias='needsAppointment', serialization_alias='needsAppointment')
    """
    Whether bookings must be linked to a calendar appointment. Legacy resources can return null.
    """

