class Transaction(CTModel):
    """
    A single accounting transaction (a booking). Every transaction posts a given `amount` between a debit account (`accountId`) and a credit account (`contraAccountId`) within one accounting period. Equal account IDs represent a transfer from `costCenterId` to `contraCostCenterId`. Monetary values are always integers in the currency's smallest denomination (e.g. cents). A transaction that belongs to a split transaction references its parent via `splitTransactionId` and cannot be edited or deleted on its own.
    """
    deprecated: TransactionDeprecated = Field(validation_alias='@deprecated', serialization_alias='@deprecated')
    """Compatibility marker mapping the deprecated donor ID fields to their replacements."""
    account_id: int = Field(validation_alias='accountId', serialization_alias='accountId')
    """ID of the debit account the amount is posted to."""
    amount: int
    """
    Stored booking amount in minor currency units. When this is the main booking of a tax split, it excludes the separate taxTransactionId amount; add both amounts to obtain the gross input amount.
    """
    bills: _t.Optional[_t.List[Bill]] = Field(default=None)
    """Receipts attached to this booking, included when include[]=bills is requested."""
    cash_discount_amount: _t.Optional[int] = Field(default=None, validation_alias='cashDiscountAmount', serialization_alias='cashDiscountAmount')
    """
    Granted cash discount in the currency's smallest denomination (e.g. cents). `null` if no cash discount applies.
    """
    cash_discount_id: _t.Optional[int] = Field(default=None, validation_alias='cashDiscountId', serialization_alias='cashDiscountId')
    """ID of the applied cash discount, or `null` if none."""
    contra_account_id: int = Field(validation_alias='contraAccountId', serialization_alias='contraAccountId')
    """ID of the credit (contra) account the amount is posted from."""
    contra_cost_center_id: _t.Optional[int] = Field(default=None, validation_alias='contraCostCenterId', serialization_alias='contraCostCenterId')
    """
    ID of the target cost center for a cost center transfer. Required when `accountId` and `contraAccountId` are equal, otherwise it must be `null`.
    """
    cost_center_id: _t.Optional[int] = Field(default=None, validation_alias='costCenterId', serialization_alias='costCenterId')
    """
    ID of the assigned cost center, or `null` if none. For a cost center transfer this is the source cost center.
    """
    document_date: _dt.date = Field(validation_alias='documentDate', serialization_alias='documentDate')
    """
    Document date of the booking. Used for accounting-period validation, date filters and accounting reports.
    """
    document_number: str = Field(validation_alias='documentNumber', serialization_alias='documentNumber')
    """
    Document number of the transaction. Auto-generated when the accounting period increments document numbers, otherwise required on creation.
    """
    donator: _t.Optional[DomainObjectPerson] = Field(default=None)
    """
    Resolved donor person, or null when no person has been resolved. Without donor visibility the response contains a censored person placeholder.
    """
    donator_id: _t.Optional[int] = Field(default=None, validation_alias='donatorId', serialization_alias='donatorId', deprecated=True)
    """Deprecated: use `donator` instead."""
    donator_spouse: _t.Optional[DomainObjectPerson] = Field(default=None, validation_alias='donatorSpouse', serialization_alias='donatorSpouse')
    """
    Resolved spouse for joint donation receipts, or null. Without donor visibility the response contains a censored person placeholder.
    """
    donator_spouse_id: _t.Optional[int] = Field(default=None, validation_alias='donatorSpouseId', serialization_alias='donatorSpouseId', deprecated=True)
    """Deprecated: use `donatorSpouse` instead."""
    id: int
    """Unique ID of the transaction."""
    is_immutable: bool = Field(validation_alias='isImmutable', serialization_alias='isImmutable')
    """
    If a transaction is immutable, none of its fields can be changed and it cannot be deleted (it has been finalized/locked).
    """
    is_synced: bool = Field(validation_alias='isSynced', serialization_alias='isSynced')
    """True, if the transaction has been created through a sync."""
    is_waiver_of_reimbursement_of_expenses: bool = Field(validation_alias='isWaiverOfReimbursementOfExpenses', serialization_alias='isWaiverOfReimbursementOfExpenses')
    """True, if this transaction is a waiver of reimbursement of expenses ("Aufwandsspende")."""
    meta: MetaDataEntityId
    note: _t.Optional[str] = Field(default=None)
    """
    Free-text booking note. Null when unset or hidden because the current user may view the transaction but not its donor information.
    """
    permissions: _t.Optional[TransactionPermissions] = Field(default=None)
    """
    Permissions calculated for the current caller, or null when this booking was serialized without a permission collection, for example a newly generated tax child.
    """
    split_transaction_id: _t.Optional[int] = Field(default=None, validation_alias='splitTransactionId', serialization_alias='splitTransactionId')
    """ID of the parent split transaction, or `null` if this is a normal standalone transaction."""
    storno_base_id: _t.Optional[int] = Field(default=None, validation_alias='stornoBaseId', serialization_alias='stornoBaseId')
    """Reference to the transaction which gets stornoed by this transaction."""
    storno_transaction_id: _t.Optional[int] = Field(default=None, validation_alias='stornoTransactionId', serialization_alias='stornoTransactionId')
    """Reference to the transaction which stornoed this transaction."""
    tax_base_id: _t.Optional[int] = Field(default=None, validation_alias='taxBaseId', serialization_alias='taxBaseId')
    """Reference to the transaction which is the base for a tax split booking."""
    tax_rate_id: _t.Optional[int] = Field(default=None, validation_alias='taxRateId', serialization_alias='taxRateId')
    """
    If a tax rate is set for the transaction, the corresponding tax transaction is returned in the field taxTransactionId.
    """
    tax_transaction_id: _t.Optional[int] = Field(default=None, validation_alias='taxTransactionId', serialization_alias='taxTransactionId')
    """Reference to the transaction which is a split booking for taxes."""
    transaction_date: _dt.date = Field(validation_alias='transactionDate', serialization_alias='transactionDate')
    """
    Date on which the transaction was created, derived from meta.createdDate. Date filters and accounting reports use documentDate.
    """

class TransactionBatchFilter(CTModel):
    """
    One accounting-period scope. Conditions within it are combined with AND; filter objects are combined with OR. Empty includeIds/excludeIds arrays impose no ID restriction. Exclusions apply only inside their own filter.
    """
    account_ids: _t.Optional[_t.List[int]] = Field(default=None, validation_alias='accountIds', serialization_alias='accountIds')
    """
    Filter by account/contra account. All transactions match, where either account or contra account is in the list.
    """
