    """ID of accounting period to get master data for"""
    cost_center_ids: _t.Optional[_t.List[int]] = Field(default=None, validation_alias='costCenterIds', serialization_alias='costCenterIds')
    """Filter by cost centers."""
    created_pid: _t.Optional[int] = Field(default=None, validation_alias='createdPid', serialization_alias='createdPid')
    """
    Filter by person ID. Get all transactions the person has created. But only show those the user can see.
    """
