class WikiCategory(CTModel):
    """A category organizes wiki pages and is the unit of wiki access permissions."""
    campus_id: _t.Optional[int] = Field(default=None, validation_alias='campusId', serialization_alias='campusId')
    """Campus association, or null when no campus is assigned."""
    file_access_without_permission: bool = Field(validation_alias='fileAccessWithoutPermission', serialization_alias='fileAccessWithoutPermission')
    """
    Whether files in this wiki category can be read without category-view permission. This flag does not make the wiki pages themselves public.
    """
    in_menu: bool = Field(validation_alias='inMenu', serialization_alias='inMenu')
    """
    Whether the category should appear in navigation menus; it is still returned by the category catalog when false.
    """
    name: str
    """Category name; unlike page titles it is not trimmed."""
    sort_key: int = Field(validation_alias='sortKey', serialization_alias='sortKey')
    """Sort order; negative values are accepted."""
    id: int
    """Wiki category ID used in category/page endpoint URLs."""
    name_translated: str = Field(validation_alias='nameTranslated', serialization_alias='nameTranslated')
    """Display name translated for the current request language."""
    permissions: GroupWikiCategoryPagesItemCategoryPermissions
    """
    Page-operation hints based on category edit rights. Populated by the category list; normally empty in create/update and embedded page categories.
    """

