class WikiPage(CTModel):
    """
    Wiki page metadata for one version. Text and previews are optional enrichments depending on the endpoint. A page is addressed by category ID and stable GUID; version identifies its revision.
    """
    deprecated: SimpleWikiPageDeprecated = Field(validation_alias='@deprecated', serialization_alias='@deprecated')
    """Compatibility marker used by existing clients."""
    guid: str
    """Stable page GUID across versions in its category."""
    identifier: _t.Optional[str] = Field(default=None, deprecated=True)
    """Deprecated alias for `guid`. Use `guid` instead."""
    is_markdown: bool = Field(validation_alias='isMarkdown', serialization_alias='isMarkdown')
    """Whether page text is Markdown rather than legacy HTML."""
    meta: MetaDataEntityPerson
    on_startpage: bool = Field(validation_alias='onStartpage', serialization_alias='onStartpage')
    """Whether the page is configured to appear on the wiki start page."""
    permissions: SimpleWikiPagePermissions
    """
    Page editing/deletion capabilities for the current user; system pages have additional restrictions.
    """
    redirect_to: _t.Optional[str] = Field(default=None, validation_alias='redirectTo', serialization_alias='redirectTo')
    """
    Stored redirect title. API reads return the page and this value; they do not follow the redirect.
    """
    search_preview: _t.Optional[str] = Field(default=None, validation_alias='searchPreview', serialization_alias='searchPreview')
    """
    Query-focused preview snippet. Present when the page list endpoint is called with a search query.
    """
    text: str
    text_preview: _t.Optional[str] = Field(default=None, validation_alias='textPreview', serialization_alias='textPreview')
    """
    Unrendered prefix of stored page text, truncated by Unicode characters. May contain raw HTML or incomplete markup. Present only with include[]=preview; not sanitized like text.
    """
    title: str
    version: int
    """Revision number of this page."""
    wiki_category: WikiCategory = Field(validation_alias='wikiCategory', serialization_alias='wikiCategory')
    """A category organizes wiki pages and is the unit of wiki access permissions."""

